---@class QTE4Mgr
local QTE4Mgr = Class('QTE4Mgr')

function QTE4Mgr:__init()
    --
end

function QTE4Mgr:__delete()
    --
end

function QTE4Mgr:Awake()
end

function QTE4Mgr:Start()
end

function QTE4Mgr:Initialize()
    self.processor = self.controller.gameObject:GetComponentInChildren(typeof(ChapterProcessor))
    self.markers = self.processor:GetAllWaitTLFinishMarkers()
    local directors = self.controller.gameObject:GetComponentsInChildren(typeof(CS.UnityEngine.Playables.PlayableDirector), true)
    for i = 1, directors.Length do
        local str = directors[i - 1].name
        if str == "OP4_part02_2"  then
            local director = directors[i - 1]
            local vec = director.transform.localPosition
            vec.y = 100
            director.transform.localPosition = vec
        end
    end
    
end

function QTE4Mgr:StartPlay()
    self.waitCo = cs_coroutine.start(function()

        printInfo("qte4 start")
        local director = nil
        local pre = nil
        if isNull(self.markers) then
            return
        end

        for i = 1, self.markers.Count do
            director = self.markers[i - 1].Director:Resolve(self.processor.DirectorControl)
            if not isNull(director) then
                KTool.SetActive(director.gameObject, true)

                --self:BindModel(director, self.model)
                if director.name == "OP4_part02_1" then

                    if not QTEReview then
                        CS.Engine.UI.UIModule.Clear()
                    end
                    
                    local coWait = CoWait.Start()
                    for i, v in support.list_ipairs(UIModule.CurrentScreen.dialogs) do
                        coWait:Coroutine(UIModule.CloseDialog(v, true))
                        printInfo(v.Argument.id)
                    end
                    while not coWait.IsFinish do
                        coroutine.yield()
                    end

                    Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, true)
                    
                    --GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome, hasExcluded = false }, nil, Constants.LoadingType.MainHome)
                    --CS.Engine.UI.UIModule.CloseDialogById(Constants.UITypeIds.BattleScene)
                    BattleViewMgr:OnDestroy()
                    CS.UnityEngine.LightmapSettings.lightProbes = nil
                    --BattleViewMgr = nil


                elseif director.name == "OP4_part01" then
                    --BattleViewMgr:BindRoleInEnterTimeline(director)
                    if BattleViewMgr.reuseRoleInstanceData ~= nil then
                        for k,v in pairs(BattleViewMgr.reuseRoleInstanceData) do

                            KTool.SetActive(v.obj, false)
                        end
                    end

                    if BattleViewMgr.rootNode ~= nil then
                        KTool.SetActive(BattleViewMgr.rootNode, false)
                    end
                    
                end

                if not isNull(pre) then
                    KTool.SetActive(pre, false)
                end

                pre = director
                director:Play()

                if not isNull(self.processor.OnSingleChapterStart) then
                    self.processor.OnSingleChapterStart(director)
                end

                coroutine.yield(WaitForTimelineFinish(director))

                if not isNull(self.processor.OnSingleChapterFinish) then
                    self.processor.OnSingleChapterFinish(director)
                end

                --if director.gameObject.name == "" then
                --    KTool.SetActive(self.model, false)
                --end
            end
        end



        if not isNull(self.processor.OnChapterFinish) then
            self.processor.OnChapterFinish()
        end



        printInfo("qte4 end")
    end)

    return self.waitCo
end

function QTE4Mgr:OnDestroy()
    if self.waitCo then
        cs_coroutine.stop(self.waitCo)
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return QTE4Mgr